def remove_file(file_path: Path) -> None:
    """Delete `file_path` if it still exists."""
    try:
        file_path.unlink()
    except FileNotFoundError:
        # Do nothing, this is the nominal case.
        pass
    except OSError:
        # Never let the clean up of a temporary file hide the real error.
        pass


def create_temp_file(prefix: str) -> Path:
    """Create an empty temporary file inside the Memory File System, and return its
    path.

    The file descriptor is closed immediately: only the path is needed, and keeping it
    open would leak one file descriptor per worker and per call.
    """
    with NamedTemporaryFile(
        prefix=prefix, suffix=SUFFIX, dir=MEMORY_FS_ROOT, delete=False
    ) as file_descriptor:
        return Path(file_descriptor.name)


def get_workers_result(
    nb_workers: int,
    progress_bars,
    master_workers_queue: multiprocessing.Queue,
    results_promise,
    progresses_length,
) -> None:
    """Monitor the workers until all of them are done (successfully or not), while
    keeping the progress bars up to date."""
    progresses = [0] * nb_workers
    workers_status = [WorkerStatus.Running] * nb_workers
    generation = count()

    while any(
        (worker_status == WorkerStatus.Running for worker_status in workers_status)
    ):
        try:
            message: Tuple[int, WorkerStatus, Any] = master_workers_queue.get(
                timeout=WORKERS_HEALTH_CHECK_INTERVAL
            )
        except queue.Empty:
            if results_promise.ready():
                # Every worker is done but at least one of them did not report its
                # status (this happens for instance when a worker process is killed).
                # `get` re-raises the error, if any, instead of waiting forever.
                results_promise.get()
                break

            continue

        worker_index, worker_status, payload = message
        workers_status[worker_index] = worker_status

        if worker_status == WorkerStatus.Success:
            progresses[worker_index] = progresses_length[worker_index]
            progress_bars.update(progresses)
        elif worker_status == WorkerStatus.Running:
            progress = cast(int, payload)
            progresses[worker_index] = progress

            if next(generation) % nb_workers == 0:
                progress_bars.update(progresses)
        elif worker_status == WorkerStatus.Error:
            progress_bars.set_error(worker_index)
            progress_bars.update(progresses)


